export const getEndSupplementUrl = (supplementId: string,
    params?: EndSupplementParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/supplements/${supplementId}?${stringifiedParams}` : `/api/supplements/${supplementId}`
}

/**
 * No supplement from `end_from` on; shifts before keep it. Without a day, or when it would only start on that
 * day or later, the supplement is deleted.
 * @summary End Supplement
 */
export const endSupplement = async (supplementId: string,
    params?: EndSupplementParams, options?: Parameters<typeof apiFetch>[1]): Promise<endSupplementResponse> => {

  return apiFetch<endSupplementResponse>(getEndSupplementUrl(supplementId,params),
  {
    ...options,
    method: 'DELETE'


  }
);}





